"""Transforms a dict with unique sequential integer indices into an array"""
def arrayizeDict(g: Any) -> object {
    mk = max(g.keys());
    ga = [None] * mk;
    for (k, v) in g.items() {
        ga[(k - 1)] = v;
    }
    return ga;
}

"""VPD dependent reduction function of the biome dependent potential conductance"""
def mVPD(vpd: Any, vpdclose: Any, vpdopen: Any) -> object {
    if (vpd <= vpdopen) {
        return 1.0;
    } elif (vpd >= vpdclose) {
        return 1.0;
    } else {
        return ((vpdclose - vpd) / (vpdclose - vpdopen));
    }
}

